import React from 'react';
import { Chart as ChartJS, ArcElement, Tooltip, Legend } from 'chart.js';
import { Doughnut } from 'react-chartjs-2';
import {
  Activity,
  Gauge,
  Zap,
  Thermometer,
  PlayCircle,
  PauseCircle,
  Wrench,
  Sparkles,
  Layers,
  BarChart3,
  Factory,
} from 'lucide-react';
import { useNavigate } from 'react-router-dom';

ChartJS.register(ArcElement, Tooltip, Legend);

const StatusChart = ({ running = 17, idle = 2, maintenance = 1 }) => {
  const navigate = useNavigate();
  const total = running + idle + maintenance || 20;

  const runningPct = Math.round((running / total) * 100);
  const idlePct = Math.round((idle / total) * 100);
  const maintPct = Math.round((maintenance / total) * 100);

  const data = {
    labels: [
      `Running (${running} / ${runningPct}%)`,
      `Idle (${idle} / ${idlePct}%)`,
      `Maintenance (${maintenance} / ${maintPct}%)`,
    ],
    datasets: [
      {
        data: [running, idle, maintenance],
        backgroundColor: [
          'rgba(16, 185, 129, 0.95)',
          'rgba(245, 158, 11, 0.95)',
          'rgba(244, 63, 94, 0.95)',
        ],
        borderColor: ['#ffffff', '#ffffff', '#ffffff'],
        borderWidth: 3,
        hoverOffset: 10,
      },
    ],
  };

  const options = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        position: 'bottom',
        labels: {
          color: 'var(--text-primary)',
          font: { family: "'Plus Jakarta Sans', sans-serif", size: 12, weight: '800' },
          padding: 12,
          usePointStyle: true,
          pointStyle: 'circle',
        },
      },
      tooltip: {
        backgroundColor: '#0F172A',
        titleColor: '#FFFFFF',
        bodyColor: '#E2E8F0',
        borderColor: '#E2E8F0',
        borderWidth: 1,
        padding: 10,
      },
    },
    cutout: '62%',
  };

  // Status Tier Breakdown Details
  const statusDetails = [
    {
      label: 'Running Assets',
      count: running,
      percentage: runningPct,
      color: 'var(--status-running)',
      bgColor: 'var(--status-running-bg)',
      borderColor: 'rgba(16, 185, 129, 0.3)',
      icon: PlayCircle,
      desc: 'Active Telemetry Sync',
    },
    {
      label: 'Idle Assets',
      count: idle,
      percentage: idlePct,
      color: 'var(--status-idle)',
      bgColor: 'var(--status-idle-bg)',
      borderColor: 'rgba(245, 158, 11, 0.3)',
      icon: PauseCircle,
      desc: 'Standby / Roll Reload',
    },
    {
      label: 'Maintenance',
      count: maintenance,
      percentage: maintPct,
      color: 'var(--status-maintenance)',
      bgColor: 'var(--status-maintenance-bg)',
      borderColor: 'rgba(244, 63, 94, 0.3)',
      icon: Wrench,
      desc: 'Bearing Overhaul Active',
    },
  ];

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '0.85rem', height: '100%' }}>
      {/* Prominent Donut Chart Canvas */}
      <div style={{ height: '230px', width: '100%', position: 'relative' }}>
        <Doughnut data={data} options={options} />
        {/* Center Donut Counter */}
        <div
          style={{
            position: 'absolute',
            top: '38%',
            left: '50%',
            transform: 'translate(-50%, -50%)',
            textAlign: 'center',
            pointerEvents: 'none',
          }}
        >
          <div style={{ fontSize: '2.6rem', fontWeight: '900', color: 'var(--text-primary)', lineHeight: 1 }}>{total}</div>
          <div style={{ fontSize: '0.75rem', fontWeight: '800', color: 'var(--text-muted)', marginTop: '4px', letterSpacing: '0.5px' }}>
            TOTAL WEAVING LOOMS
          </div>
        </div>
      </div>

      {/* 4 PRIMARY METRICS WIDGET BOX */}
