        style={{
          background: 'var(--bg-primary)',
          border: '1px solid var(--border-subtle)',
          borderRadius: 'var(--radius-sm)',
          padding: '0.85rem 1rem',
          display: 'grid',
          gridTemplateColumns: 'repeat(2, 1fr)',
          gap: '0.75rem',
        }}
      >
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
          <Gauge size={16} style={{ color: 'var(--status-running)' }} />
          <div>
            <div style={{ fontSize: '0.72rem', color: 'var(--text-secondary)', fontWeight: '800' }}>FLEET OEE</div>
            <div style={{ fontSize: '0.95rem', fontWeight: '800', color: 'var(--text-primary)' }}>96.4%</div>
          </div>
        </div>

        <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
          <Activity size={16} style={{ color: 'var(--accent-primary)' }} />
          <div>
            <div style={{ fontSize: '0.72rem', color: 'var(--text-secondary)', fontWeight: '800' }}>OUTPUT RATE</div>
            <div style={{ fontSize: '0.95rem', fontWeight: '800', color: 'var(--text-primary)' }}>1,485 M/hr</div>
          </div>
        </div>

        <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
          <Zap size={16} style={{ color: 'var(--status-idle)' }} />
          <div>
            <div style={{ fontSize: '0.72rem', color: 'var(--text-secondary)', fontWeight: '800' }}>ACTIVE SENSORS</div>
            <div style={{ fontSize: '0.95rem', fontWeight: '800', color: 'var(--text-primary)' }}>136 IoT Feeds</div>
          </div>
        </div>

        <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
          <Thermometer size={16} style={{ color: 'var(--status-maintenance)' }} />
          <div>
            <div style={{ fontSize: '0.72rem', color: 'var(--text-secondary)', fontWeight: '800' }}>AVG TEMP</div>
            <div style={{ fontSize: '0.95rem', fontWeight: '800', color: 'var(--text-primary)' }}>54.2°C</div>
          </div>
        </div>
      </div>

      {/* SECTION BELOW METRICS: DETAILED STATUS BREAKDOWN TIERS */}
      <div style={{ display: 'flex', flexDirection: 'column', gap: '0.65rem' }}>
        <div style={{ fontSize: '0.78rem', fontWeight: '800', color: 'var(--text-primary)', display: 'flex', alignItems: 'center', gap: '0.4rem', textTransform: 'uppercase', letterSpacing: '0.5px' }}>
          <Layers size={14} style={{ color: 'var(--accent-primary)' }} /> STATUS TIER ANALYTICS
        </div>

        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '0.5rem' }}>
          {statusDetails.map((sd, idx) => {
            const Icon = sd.icon;
            return (
              <div
                key={idx}
                style={{
                  background: sd.bgColor,
                  border: `1px solid ${sd.borderColor}`,
                  borderRadius: '8px',
                  padding: '0.6rem 0.5rem',
                  textAlign: 'center',
                }}
              >
                <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '0.25rem', fontSize: '0.7rem', fontWeight: '800', color: sd.color }}>
                  <Icon size={12} /> {sd.label.split(' ')[0]}
                </div>
                <div style={{ fontSize: '1.25rem', fontWeight: '900', color: 'var(--text-primary)', margin: '2px 0' }}>
                  {sd.count} <span style={{ fontSize: '0.7rem', color: 'var(--text-muted)', fontWeight: '700' }}>({sd.percentage}%)</span>
                </div>
                <div style={{ fontSize: '0.66rem', fontWeight: '700', color: 'var(--text-secondary)' }}>
                  {sd.desc}
