        style={{
          background: 'var(--bg-primary)',
          border: '1px solid var(--border-subtle)',
          borderRadius: 'var(--radius-sm)',
          padding: '0.75rem 0.85rem',
          display: 'flex',
          flexDirection: 'column',
          gap: '0.5rem',
        }}
      >
        <div style={{ fontSize: '0.75rem', fontWeight: '800', color: 'var(--text-primary)', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <span style={{ display: 'flex', alignItems: 'center', gap: '0.35rem' }}>
            <BarChart3 size={14} style={{ color: 'var(--status-running)' }} /> Weaving Loom Speed Index
          </span>
          <span style={{ fontSize: '0.74rem', color: 'var(--status-running)', fontWeight: '800' }}>1,050 RPM (95% Target)</span>
        </div>
        <div style={{ height: '6px', background: 'var(--border-subtle)', borderRadius: '3px', overflow: 'hidden' }}>
          <div style={{ width: '95%', height: '100%', background: 'linear-gradient(90deg, #10b981, #38bdf8)', borderRadius: '3px' }}></div>
        </div>

        <div style={{ fontSize: '0.75rem', fontWeight: '800', color: 'var(--text-primary)', display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginTop: '3px' }}>
