        </div>
        <div style={{ height: '6px', background: 'var(--border-subtle)', borderRadius: '3px', overflow: 'hidden' }}>
          <div style={{ width: '99.1%', height: '100%', background: 'linear-gradient(90deg, #2563eb, #8b5cf6)', borderRadius: '3px' }}></div>
        </div>
      </div>

      {/* QUICK OPERATIONS ACTION BUTTON FOOTER */}
      <div style={{ marginTop: 'auto', display: 'flex', gap: '0.5rem', paddingTop: '0.35rem' }}>
        <button
